vars.legacy_script:
var driver = DDT.ExcelDriver('C:\Data\users.xlsx', 'Sheet1');
while (!driver.EOF()) {
  Aliases.browser.pageLogin.textboxUser.SetText(driver.Value('username'));
  Aliases.browser.pageLogin.textboxPass.SetText(driver.Value('password'));
  Aliases.browser.pageLogin.buttonLogin.Click();
  driver.Next();
}
DDT.CloseDriver(driver.Name);

var resp = aqHttp.Get('https://api.example.com/orders/1001', 'Authorization: Bearer ' + token);
if (resp.StatusCode != 200) Log.Error('Order API failed');
var order = JSON.parse(resp.Text);
if (order.status != 'CONFIRMED') Log.Error('Wrong status');

var page = Aliases.browser.pageFeed;
while (page.FindChild('innerText', 'Post #100', 1).Exists == false) {
  page.Keys('[PageDown]');
  aqUtils.Delay(500);
}
